A continuación se presenta un ejemplo de código para crear un bot de Discord que utiliza el módulo Discord.js v14, con un comando de ban:

1. Primero, instala los paquetes necesarios utilizando npm:

```
npm install discord.js dotenv
```

2. Crea un nuevo archivo llamado `.env` en la raíz de tu proyecto y agrega tu clave de desarrollo de Discord:

```
TOKEN=<tu-clave-de-desarrollo-de-Discord>
```

3. Crea un nuevo archivo llamado `index.js` en la raíz de tu proyecto:

```javascript
const { Client, Intents } = require('discord.js');
require('dotenv').config();

const client = new Client({
  intents: [
    Intents.FLAGS.GUILDS,
    Intents.FLAGS.GUILD_MESSAGES,
    Intents.FLAGS.GUILD_MEMBERS,
    Intents.FLAGS.GUILD_BANS_ADD,
    Intents.FLAGS.GUILD_BANS_REMOVE,
    Intents.FLAGS.GUILD_VOICE_STATES,
  ],
});

client.on('ready', () => {
  console.log(`Bot listo! ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  if (commandName === 'ban') {
    const member = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason');

    if (!member.bannable) {
      return interaction.reply({
        content: 'Este miembro no puede ser baneado.',
        ephemeral: true,
      });
    }

    await interaction.guild.members.ban(member.id, { reason });

    return interaction.reply({
      content: `${member.user.tag} ha sido baneado por: ${reason}`,
    });
  }
});

client.login(process.env.TOKEN);
```

4. Agrega este comando de ban a tu archivo de comandos (por ejemplo, `commands.json`):

```json
{
  "name": "ban",
  "description": "Banea a un usuario del servidor.",
  "options": [
    {
      "name": "user",
      "description": "Usuario a baneo.",
      "type": "USER",
      "required": true
    },
    {
      "name": "reason",
      "description": "Motivo del ban.",
      "type": "STRING",
      "required": false
    }
  ]
}
```

5. Actualiza tu archivo `index.js` para cargar los comandos:

```javascript
const { Client, Intents } = require('discord.js');
const { Collection } = require('discord.js');
const { readFileSync } = require('fs');
const { join } = require('path');
require('dotenv').config();

const client = new Client({
  intents: [
    Intents.FLAGS.GUILDS,
    Intents.FLAGS.GUILD_MESSAGES,
    Intents.FLAGS.GUILD_MEMBERS,
    Intents.FLAGS.GUILD_BANS_ADD,
    Intents.FLAGS.GUILD_BANS_REMOVE,
    Intents.FLAGS.GUILD_VOICE_STATES,
  ],
});

const commands = [];
const commandFiles = readFileSync(join(__dirname, 'commands'), 'utf8')
  .toString()
  .split('\n')
  .filter(file => file.endsWith('.json'));

for (const file of commandFiles) {
  const command = JSON.parse(file);
  commands.push(command);
}

client.on('ready', () => {
  console.log(`Bot listo! ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = commands.find(cmd => cmd.name === interaction.commandName);

  if (!command) return;

  if (command.options.length > 0) {
    if (!interaction.options._hoistedOptions[0]) {
      return interaction.reply({
        content: 'Por favor, proporciona un argumento válido para este comando.',
        ephemeral: true,
      });
    }

    const options = interaction.options._hoistedOptions.map(option => {
      if (option.type === 'USER') {
        return client.users.cache.get(option.value);
      }

      return option.value;
    });

    await command.execute(interaction, ...options);
  } else {
    await command.execute(interaction);
  }
});

client.login(process.env.TOKEN);
```

6. Crea un nuevo directorio llamado `commands` en la raíz de tu proyecto y agrega un nuevo archivo llamado `ban.json` con el siguiente contenido:

```json
{
  "name": "ban",
  "description": "Banea a un usuario del servidor.",
  "options": [
    {
      "name": "user",
      "description": "Usuario a baneo.",
      "type": "USER",
      "required": true
    },
    {
      "name": "reason",
      "description": "Motivo del ban.",
      "type": "STRING",
      "required": false
    }
  ]
}
```

7. Ahora, asegúrate de haber instalado correctamente los paquetes y ejecuta el comando `node index.js` en tu terminal para correr tu bot de Discord. ¡Y eso es todo! Ahora puedes usar el comando `/ban` para baneo a un miembro del servidor proporcionando un usuario y (opcionalmente) un motivo de ban. Recuerda que debes configurar tu webhook para que tu bot pueda funcionar correctamente.

Aquí hay un ejemplo de código que implementa la conversión de texto de Markdown a HTML utilizando la biblioteca Boost.Spirit X3:

```cpp
#include <boost/spirit/home/x3.hpp>
#include <boost/fusion/adapted/std_vector.hpp>
#include <iostream>
#include <string>
#include <vector>

namespace x3 = boost::spirit::x3;

// Reglas de gramática para Markdown
auto const markdown_rule = x3::rule<struct markdown_rule, std::string>{"markdown"}
    = x3::lit("#") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("##") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("###") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("####") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("#####") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("######") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("*") >> x3::alpha >> *x3::alnum >> x3::eol
    | x3::lit("1. ") >> *x3::digit >> *x3::alnum >> x3::eol
    | x3::lit("[") >> *x3::print >> *x3::char_[(c == ']')] >> x3::lit("]") >> *x3::char_(" ") >> x3::lit("(") >> *x3::print >> *x3::char_[(c == ')')] >> x3::eol
    | x3::lit("```") >> *x3::print >> x3::lit("```") >> x3::eol
    | x3::lit("<") >> *x3::print >> x3::lit(">") >> x3::eol
    | x3::lit("-") >> *x3::alnum >> x3::eol
    | *x3::print;

// Reglas de gramática para HTML
auto const html_rule = x3::rule<struct html_rule, std::string>{"html"}
    = x3::lit("<h") >> *x3::digit >> *x3::alnum >> x3::lit(">") >> *x3::print >> x3::lit("</") >> x3::attr<4>("h") >> x3::lit(">")
    | x3::lit("<p>") >> *x3::print >> x3::lit("</p>")
    | x3::lit("<ul>") >> *x3::lit("<li>") >> *x3::print >> x3::lit("</li>") >> *x3::lit("</ul>")
    | x3::lit("<a href=") >> *x3::print >> x3::lit(">") >> *x3::print >> x3::lit("</a>")
    | x3::lit("<pre>") >> *x3::print >> x3::lit("</pre>")
    | x3::lit("<code>") >> *x3::print >> x3::lit("</code>")
    | x3::lit("<strong>") >> *x3::print >> x3::lit("</strong>")
    | x3::lit("<em>") >> *x3::print >> x3::lit("</em>")
    | x3::lit("<img src=") >> *x3::print >> x3::lit(">");

// Función de conversión de Markdown a HTML
std::string convert_to_html(const std::string& markdown) {
    std::string html;
    auto f = markdown.begin();
    auto l = markdown.end();

    if (!x3::parse(f, l, markdown_rule, html)) {
        std::cerr << "Error: fallo en la conversión de Markdown a HTML." << std::endl;
        return "";
    }

    return html;
}

int main() {
    std::string markdown = R"(# Encabezado de nivel 1
## Encabezado de nivel 2
### Encabezado de nivel 3
#### Encabezado de nivel 4
##### Encabezado de nivel 5
###### Encabezado de nivel 6

* Item de lista sin numeración
1. Item de lista numerado
2. Otra lista numerada

[Clic aquí](http://www.example.com) para más información.

Código:
```cpp
#include <iostream>

int main() {
    std::cout << "Hola, mundo!" << std::endl;
    return 0;
}

Imagen:
![Logo de Boost](https://boost.org/images/logo.png)
)";

    std::string html = convert_to_html(markdown);

    std::cout << "Markdown:\n" << markdown << "\n\n";
    std::cout << "HTML:\n" << html << std::endl;

    return 0;
}
```

El código anterior define dos reglas de gramática utilizando Boost.Spirit X3: una para Markdown y otra para HTML. Luego, define una función `convert_to_html` que toma un texto de entrada en formato Markdown y lo convierte en texto de salida en formato HTML utilizando las reglas definidas.

