Aquí está un ejemplo de cómo leer un archivo de texto línea por línea en C++ y contar el número de apariciones de una palabra específica:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string fileName; // nombre del archivo
    string wordToSearch; // palabra a buscar
    int count = 0; // contador de apariciones

    // Solicitar el nombre del archivo y la palabra a buscar al usuario
    cout << "Introduzca el nombre del archivo: ";
    cin >> fileName;

    cout << "Introduzca la palabra a buscar: ";
    cin >> wordToSearch;

    // Abrir el archivo de texto para lectura
    ifstream file(fileName);

    if (!file.is_open()) {
        cerr << "Error: No se pudo abrir el archivo " << fileName << endl;
        return 1;
    }

    string line;

    // Leer línea por línea y contar apariciones de la palabra especificada
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != string::npos) {
            count++;
            pos += wordToSearch.length();
        }
    }

    // Cerrar el archivo de texto
    file.close();

    // Mostrar el resultado
    cout << "El número de apariciones de '" << wordToSearch << "' en " << fileName << " es: " << count << endl;

    return 0;
}
```

Este programa solicita al usuario el nombre del archivo y la palabra a buscar, abre el archivo, lee línea por línea, cuenta las apariciones de la palabra especificada y finalmente imprime el resultado. 

Por supuesto, asegúrese de que el archivo de texto esté en el mismo directorio que el programa C++ para que el programa pueda encontrarlo. Si el archivo está en una ruta distinta, modifique el nombre de archivo proporcionado en `fileName` para incluir la ruta completa del archivo. Además, asegúrese de tener la biblioteca de archivos (fstream) incluida en su proyecto para que pueda compilar correctamente.

Aquí hay un ejemplo de código en C++ para encontrar los elementos comunes en dos matrices sin utilizar ninguna estructura de datos adicional:

```cpp
#include <iostream>
#include <vector>

using namespace std;

int main() {
    int n, m;
    cout << "Ingrese el número de filas de la primera matriz: ";
    cin >> n;
    cout << "Ingrese el número de columnas de la primera matriz: ";
    cin >> m;

    int arr1[n][m];
    cout << "Ingrese los elementos de la primera matriz:\n";
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> arr1[i][j];
        }
    }

    cout << "Ingrese el número de filas de la segunda matriz: ";
    cin >> n;
    cout << "Ingrese el número de columnas de la segunda matriz: ";
    cin >> m;

    int arr2[n][m];
    cout << "Ingrese los elementos de la segunda matriz:\n";
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            cin >> arr2[i][j];
        }
    }

    // Comprobar que las matrices tienen el mismo tamaño
    if (n != m) {
        cout << "Las matrices deben tener el mismo tamaño.\n";
        return 0;
    }

    // Comprobar los elementos comunes
    vector<int> common;
    for (int I = 0; I < n; i++) {
        for (int j = 0; j < m; j++) {
            if (arr1[i][j] == arr2[i][j]) {
                common.push_back(arr1[i][j]);
            }
        }
    }

    // Imprimir los elementos comunes
    if (common.empty()) {
        cout << "No hay elementos comunes en las matrices.\n";
    } else {
        cout << "Elementos comunes:\n";
        for (int I : common) {
            cout << I << " ";
        }
        cout << endl;
    }

    return 0;
}
```

Este programa solicita al usuario la dimensión de las matrices, luego solicita los elementos de cada matriz y finalmente encuentra los elementos comunes entre las dos matrices. Si las matrices tienen diferentes dimensiones, el programa informará al usuario.

Se utilizan dos bucles anidados para recorrer cada elemento de las matrices, y se compara cada elemento en la misma posición en ambas matrices. Si se encuentran iguales, se agregan a una lista de elementos comunes.

Por último, se imprime la lista de elementos comunes, o se informa que no hay elementos comunes si la lista está vacía. Este enfoque es eficiente en términos de espacio, ya que no se utilizan estructuras de datos adicionales. Sin embargo, esto puede no ser eficiente en términos de tiempo si las matrices son grandes, ya que se realiza una comparación de cada elemento en ambas matrices. En tales casos, se pueden utilizar técnicas de optimización como el uso de hash tables para acelerar el proceso.
